import { useState } from 'react'
import { useData } from '@/context/DataContext'
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import {
  Building2,
  Plus,
  Pencil,
  Trash2,
  MapPin,
  User,
  CheckCircle2,
  LayoutGrid,
  Wifi,
  WifiOff,
} from 'lucide-react'
import { FactoryForm } from '@/components/FactoryForm'
import { Factory } from '@/lib/types'
import { cn } from '@/lib/utils'
import { useToast } from '@/hooks/use-toast'
import { SecurityGate } from '@/components/SecurityGate'

export default function Factories() {
  const {
    factories,
    deleteFactory,
    currentFactoryId,
    setCurrentFactoryId,
    connectionStatus,
  } = useData()
  const { toast } = useToast()

  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const [editingFactory, setEditingFactory] = useState<Factory | undefined>(
    undefined,
  )
  const [deleteId, setDeleteId] = useState<string | null>(null)

  // Security Gate State
  const [securityOpen, setSecurityOpen] = useState(false)
  const [pendingAction, setPendingAction] = useState<(() => void) | null>(null)
  const [securityTitle, setSecurityTitle] = useState('Área Segura')
  const [securityDescription, setSecurityDescription] = useState(
    'Esta ação requer autorização de nível gerencial. Digite a senha para continuar.',
  )

  // Always require password for factory modification actions
  const handleSecureAction = (
    action: () => void,
    title: string = 'Área Segura',
    description: string = 'Esta ação requer autorização de nível gerencial. Digite a senha para continuar.',
  ) => {
    setPendingAction(() => action)
    setSecurityTitle(title)
    setSecurityDescription(description)
    setSecurityOpen(true)
  }

  const handleSecuritySuccess = () => {
    setSecurityOpen(false)
    if (pendingAction) pendingAction()
    setPendingAction(null)
  }

  const handleCreate = () => {
    handleSecureAction(
      () => {
        setEditingFactory(undefined)
        setIsDialogOpen(true)
      },
      'Nova Fábrica',
      'Para adicionar uma nova fábrica, é necessário autorização. Digite a senha.',
    )
  }

  const handleEditClick = (factory: Factory) => {
    setEditingFactory(factory)
    setIsDialogOpen(true)
  }

  const handleDeleteRequest = (factory: Factory) => {
    if (factories.length <= 1) {
      toast({
        title: 'Ação Bloqueada',
        description: 'Não é possível excluir a única fábrica do sistema.',
        variant: 'destructive',
      })
      return
    }
    if (factory.id === currentFactoryId) {
      toast({
        title: 'Ação Bloqueada',
        description: 'Você não pode excluir a fábrica que está visualizando.',
        variant: 'destructive',
      })
      return
    }

    handleSecureAction(() => setDeleteId(factory.id))
  }

  const confirmDelete = () => {
    if (deleteId) {
      deleteFactory(deleteId)
      setDeleteId(null)
      toast({
        title: 'Fábrica Removida',
        description: 'A unidade foi excluída com sucesso.',
      })
    }
  }

  const handleSwitch = (id: string) => {
    setCurrentFactoryId(id)
    toast({
      title: 'Contexto Alterado',
      description: 'Visualizando dados da fábrica selecionada.',
    })
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-2 md:flex-row md:items-center md:justify-between">
        <div>
          <div className="flex items-center gap-2">
            <h2 className="text-2xl font-bold tracking-tight flex items-center gap-2">
              <Building2 className="h-6 w-6 text-primary" />
              Minhas Fábricas
            </h2>
            {connectionStatus === 'online' && (
              <Badge
                variant="outline"
                className="bg-green-50 text-green-700 border-green-200 gap-1"
              >
                <Wifi className="h-3 w-3" /> Online
              </Badge>
            )}
            {connectionStatus === 'syncing' && (
              <Badge
                variant="outline"
                className="bg-blue-50 text-blue-700 border-blue-200 gap-1 animate-pulse"
              >
                <Wifi className="h-3 w-3" /> Sincronizando
              </Badge>
            )}
            {(connectionStatus === 'offline' ||
              connectionStatus === 'error') && (
              <Badge
                variant="outline"
                className="bg-red-50 text-red-700 border-red-200 gap-1"
              >
                <WifiOff className="h-3 w-3" /> Offline
              </Badge>
            )}
          </div>
          <p className="text-muted-foreground">
            Gerencie as unidades fabris integradas ao sistema.
          </p>
        </div>

        <Button onClick={handleCreate} className="gap-2">
          <Plus className="h-4 w-4" /> Nova Fábrica
        </Button>

        <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
          <DialogContent className="sm:max-w-[425px]">
            <DialogHeader>
              <DialogTitle>
                {editingFactory ? 'Editar Fábrica' : 'Adicionar Nova Fábrica'}
              </DialogTitle>
              <DialogDescription>
                {editingFactory
                  ? 'Atualize os dados da unidade selecionada.'
                  : 'Preencha as informações para registrar uma nova planta fabril.'}
              </DialogDescription>
            </DialogHeader>
            <FactoryForm
              initialData={editingFactory}
              onSuccess={() => setIsDialogOpen(false)}
            />
          </DialogContent>
        </Dialog>
      </div>

      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {factories.map((factory) => {
          return (
            <Card
              key={factory.id}
              className={cn(
                'transition-all hover:shadow-md cursor-pointer border-l-4',
                currentFactoryId === factory.id
                  ? 'border-l-primary ring-1 ring-primary/20 bg-secondary/5'
                  : 'border-l-transparent hover:border-l-muted-foreground/30',
              )}
              onClick={() => handleSwitch(factory.id)}
            >
              <CardHeader className="pb-3">
                <div className="flex justify-between items-start">
                  <CardTitle className="text-lg font-semibold flex items-center gap-2">
                    {factory.name}
                  </CardTitle>
                  {factory.status === 'active' ? (
                    <Badge
                      variant="outline"
                      className="bg-green-50 text-green-700 border-green-200"
                    >
                      Ativa
                    </Badge>
                  ) : (
                    <Badge variant="outline" className="text-muted-foreground">
                      Inativa
                    </Badge>
                  )}
                </div>
                <CardDescription className="flex items-center gap-1">
                  <MapPin className="h-3.5 w-3.5" />
                  {factory.location}
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="flex items-center gap-2 text-sm text-muted-foreground mb-4">
                  <User className="h-4 w-4" />
                  Gerente:{' '}
                  <span className="font-medium">{factory.manager}</span>
                </div>
                <div className="flex items-center justify-between pt-2 border-t">
                  <div className="text-xs text-muted-foreground">
                    {currentFactoryId === factory.id ? (
                      <span className="flex items-center gap-1 text-primary font-medium">
                        <CheckCircle2 className="h-3 w-3" /> Selecionada
                      </span>
                    ) : (
                      <span className="flex items-center gap-1">
                        <LayoutGrid className="h-3 w-3" /> Clique para ver
                      </span>
                    )}
                  </div>
                  <div
                    className="flex gap-1 items-center"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-7 w-7"
                      onClick={() =>
                        handleSecureAction(() => handleEditClick(factory))
                      }
                    >
                      <Pencil className="h-3.5 w-3.5" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-7 w-7 text-destructive hover:text-destructive"
                      onClick={() => handleDeleteRequest(factory)}
                    >
                      <Trash2 className="h-3.5 w-3.5" />
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          )
        })}
      </div>

      <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Excluir Fábrica</AlertDialogTitle>
            <AlertDialogDescription>
              Tem certeza que deseja remover esta unidade? Esta ação não pode
              ser desfeita.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDelete}
              className="bg-destructive hover:bg-destructive/90"
            >
              Remover
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <SecurityGate
        isOpen={securityOpen}
        onOpenChange={setSecurityOpen}
        onSuccess={handleSecuritySuccess}
        title={securityTitle}
        description={securityDescription}
      />
    </div>
  )
}
